// The React Server Components entries of @margoengine/react: for each package entry dist/<name>.js, a dist/rsc/<name>.js
// that starts with 'use client' and re-exports the entry's runtime names one by one. package.json maps the
// "react-server" export condition there, so a server component can render Canvas straight from the package, while every
// other bundler loads the plain entry, which carries no module-level directive (Vite and Rollup warn once per bundled
// file that has one). Next.js rejects `export *` in a client boundary, hence the names. Run after tsc.
import { readFile, mkdir, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { parseSync } from 'rolldown/utils';

/** The runtime export names of an ES module file, following `export * from './x.js'` into sibling files. */
export async function exportNames(file, seen = new Set()) {
  if (seen.has(file)) return new Set();
  seen.add(file);
  const parsed = parseSync(file, await readFile(file, 'utf8'));
  if (parsed.errors.length) throw new Error(`${file}: ${parsed.errors[0].message}`);
  const names = new Set();
  for (const node of parsed.program.body) {
    if (node.type === 'ExportNamedDeclaration' && node.exportKind !== 'type') {
      for (const specifier of node.specifiers ?? [])
        if (specifier.exportKind !== 'type') names.add(specifier.exported.name ?? specifier.exported.value);
      const declaration = node.declaration;
      if (declaration?.id?.name) names.add(declaration.id.name);
      for (const item of declaration?.declarations ?? []) if (item.id?.name) names.add(item.id.name);
    } else if (node.type === 'ExportDefaultDeclaration') names.add('default');
    else if (node.type === 'ExportAllDeclaration' && node.exportKind !== 'type') {
      if (node.exported) names.add(node.exported.name ?? node.exported.value);
      else if (node.source.value.startsWith('.')) {
        for (const name of await exportNames(resolve(dirname(file), node.source.value), seen))
          if (name !== 'default') names.add(name);
      } else
        throw new Error(`${file}: export * from a package (${node.source.value}) cannot be listed; name the exports`);
    }
  }
  return names;
}

/** The JSX runtime entries: on the server, React's runtime with the same names. */
export const JSX_RUNTIMES = {
  'jsx-runtime': { from: 'react/jsx-runtime', names: ['Fragment', 'jsx', 'jsxs'] },
  'jsx-dev-runtime': { from: 'react/jsx-dev-runtime', names: ['Fragment', 'jsxDEV'] },
};

/** Writes dist/rsc/<entry>.js for every entry in the package's exports map and checks the map points there. */
export async function writeServerEntries(root) {
  const manifest = JSON.parse(await readFile(join(root, 'package.json'), 'utf8'));
  for (const [subpath, entry] of Object.entries(manifest.exports)) {
    const name = entry.import.replace(/^\.\/dist\//, '').replace(/\.js$/, '');
    if (entry['react-server'] !== `./dist/rsc/${name}.js`)
      throw new Error(`${manifest.name} ${subpath}: "react-server" must be ./dist/rsc/${name}.js`);
    await mkdir(join(root, 'dist/rsc'), { recursive: true });
    // A JSX runtime is called by every server component compiled with that jsxImportSource, so behind a client
    // boundary its jsx() would be a client reference; on the server it is React's own runtime (the Margo tags draw
    // only in client components, under a <Canvas>).
    const runtime = JSX_RUNTIMES[name];
    if (runtime) {
      await writeFile(
        join(root, 'dist/rsc', `${name}.js`),
        `// Generated by scripts/react-server-entries.js: the "react-server" entry, React's ${runtime.from} unchanged.\nexport { ${runtime.names.join(', ')} } from '${runtime.from}';\n`,
      );
      continue;
    }
    const names = [...(await exportNames(join(root, 'dist', `${name}.js`)))].sort();
    if (!names.length || names.includes('default'))
      throw new Error(`${manifest.name} ${subpath}: a client boundary needs named exports only`);
    await writeFile(
      join(root, 'dist/rsc', `${name}.js`),
      `'use client';\n// Generated by scripts/react-server-entries.js: the "react-server" entry, ../${name}.js behind a client boundary.\nexport { ${names.join(', ')} } from '../${name}.js';\n`,
    );
  }
}
